def get_segments(arr,color):
 groups=defaultdict(list)
 for r,c in np.argwhere(arr==color): groups[int(r+c)].append(int(c-r))
 seg=[]
 for u,ds in groups.items():
  ds=sorted(ds)
  runs=[]
  for d0 in ds:
   if not runs or d0-runs[-1][-1]>2: runs.append([d0])
   else:runs[-1].append(d0)
  for run in runs:seg.append((u,min(run),max(run)))
 return sorted(seg)
